import { test, expect } from '@playwright/test';

test.describe('Checkout Form Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
    await page.setViewportSize({ width: 375, height: 812 }); // Mobile screen size
  });

  test('should display checkout form stacked vertically on mobile', async ({ page }) => {
    const form = await page.getByRole('form', { name: /checkout/i });
    const inputs = await form.locator('input');

    for (let i = 0; i < await inputs.count(); i++) {
      const input = inputs.nth(i);
      await expect(input).toHaveCSS('display', 'block');
      await expect(input).toHaveCSS('width', '100%');
    }
  });

  test('should have a submit button at the bottom of the form', async ({ page }) => {
    const submitButton = await page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
    await expect(submitButton).toHaveCSS('margin-top', '16px'); // Example margin for spacing
  });
});
